import{useState}from'react';import{Pressable,StyleSheet,Text,View}from'@/platform/react-native';import{useLocalSearchParams}from'@/router';import{api}from'@/lib/api';import{Button,Card,Header,Input,Muted,Screen,useAppTheme}from'@/components/UI';
const suggestions=['When is our next meeting?','What did we decide about parking?','Find the waste collection announcement.','Explain the latest community policy.'];
export default function Assistant(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const[q,setQ]=useState('');const[result,setResult]=useState<any>(null);const[loading,setLoading]=useState(false);const ask=async(text=q)=>{setLoading(true);try{const r=await api.post(`/communities/${id}/assistant/ask`,{question:text,mode:'MEMBER'});setResult(r.data);setQ(text)}finally{setLoading(false)}};return <Screen scroll><Header title="CDA Assistant" subtitle="Permission-aware community search and assistance"/><View style={s.chips}>{suggestions.map(x=><Pressable key={x} onPress={()=>ask(x)} style={[s.chip,{borderColor:palette.border,backgroundColor:palette.surface}]}><Text style={{color:palette.text}}>{x}</Text></Pressable>)}</View><Input value={q} onChangeText={setQ} placeholder="Ask about meetings, decisions, posts or policies"/><Button title="Ask CDA Assistant" loading={loading} onPress={()=>q.trim()&&ask()}/>{result?<Card><Text style={[s.answer,{color:palette.text}]}>{result.answer||'I found authorised community information related to your question:'}</Text>{result.context?.decisions?.map((x:any)=><Muted key={x.Id}>• Decision: {x.Title} — {x.DecisionText}</Muted>)}{result.context?.documents?.map((x:any)=><Muted key={x.Id}>• Document: {x.Title} ({x.Category})</Muted>)}{result.context?.announcements?.slice(0,3).map((x:any)=><Muted key={x.Id}>• Announcement: {x.Title}</Muted>)}{result.context?.meetings?.slice(0,3).map((x:any)=><Muted key={x.Id}>• Meeting: {x.Title} · {new Date(x.StartDateTime).toLocaleString()}</Muted>)}<Muted style={{marginTop:10}}>The production AI provider should generate the final natural-language answer only from this permission-filtered context.</Muted></Card>:null}</Screen>};const s=StyleSheet.create({chips:{gap:8,marginBottom:10},chip:{borderWidth:1,borderRadius:13,padding:11},answer:{fontWeight:'900',marginBottom:10}})
